/* =====================================================================
   COMPUTE DOMINANCE  (n8n Code node, "Run Once for All Items")
   Input  : rows from "Read Last Dominance" (history)
   Changes: looked up by captured_at TIMESTAMP (not by row count), so it works
            with any schedule (the old version assumed 15m rows, but the
            workflow runs hourly, which made "24h" really ~4 days)
   New    : USDT dominance, USDT market cap, usdt_signal
   ===================================================================== */
const LF = '\n';
const g = $('CoinGecko Global').first().json?.data || {};

/* null/undefined/'' stay null (Number(null) would wrongly give 0) */
const num = x => {
  if (x === null || x === undefined || x === '') return null;
  const n = Number(x);
  return Number.isFinite(n) ? n : null;
};

/* ---------------- current values ---------------- */
const totalMcap = num(g.total_market_cap?.usd);
const btcD  = num(g.market_cap_percentage?.btc);
const ethD  = num(g.market_cap_percentage?.eth);
const usdtD = num(g.market_cap_percentage?.usdt);

const mc = d => (totalMcap != null && d != null ? totalMcap * d / 100 : null);
const btcMcap = mc(btcD), ethMcap = mc(ethD), usdtMcap = mc(usdtD);
const total2 = totalMcap != null && btcMcap != null ? totalMcap - btcMcap : null;
const total3 = total2 != null && ethMcap != null ? total2 - ethMcap : null;

/* ---------------- history, looked up by time ---------------- */
const now = Date.now();
const history = $input.all()
  .map(i => i.json)
  .filter(r => r && r.captured_at)
  .map(r => ({ ...r, _t: new Date(r.captured_at).getTime() }))
  .filter(r => Number.isFinite(r._t))
  .sort((a, b) => a._t - b._t);

/* row closest to "hours ago", only if it is within a sensible tolerance */
function rowAgo(hours) {
  const target = now - hours * 3600e3;
  const tol = Math.min(2, Math.max(0.75, hours * 0.15)) * 3600e3;
  let best = null, bd = Infinity;
  for (const r of history) {
    const d = Math.abs(r._t - target);
    if (d < bd) { bd = d; best = r; }
  }
  return bd <= tol ? best : null;
}
const row1h = rowAgo(1), row4h = rowAgo(4), row24h = rowAgo(24);

function pct(cur, old) {
  cur = num(cur); old = num(old);
  if (cur == null || old == null || old === 0) return null;
  return (cur - old) / old * 100;
}

const btcD1h = pct(btcD, row1h?.btc_d),   btcD4h = pct(btcD, row4h?.btc_d),   btcD24h = pct(btcD, row24h?.btc_d);
const total2_1h = pct(total2, row1h?.total2), total2_4h = pct(total2, row4h?.total2), total2_24h = pct(total2, row24h?.total2);
const total3_1h = pct(total3, row1h?.total3), total3_4h = pct(total3, row4h?.total3), total3_24h = pct(total3, row24h?.total3);

/* USDT (these columns are empty in old rows, so they stay null until ~24h of new data exists) */
const usdtD1h = pct(usdtD, row1h?.usdt_d), usdtD4h = pct(usdtD, row4h?.usdt_d), usdtD24h = pct(usdtD, row24h?.usdt_d);
const usdtMcap24h = pct(usdtMcap, row24h?.usdt_mcap);

/* ---------------- USDT signal ----------------
   USDT.D also rises just because other coins fall (USDT is stable, so its share goes up).
   So we also look at USDT's own market cap:
     FLIGHT_TO_USDT : USDT.D rising AND USDT market cap growing  -> real money moving into USDT
     PRICE_DRIVEN   : USDT.D rising but USDT market cap flat     -> mostly just the market falling
     DEPLOYING      : USDT.D falling                              -> money leaving USDT into crypto
*/
const U = { riseD: 1, fallD: -1, mcapInflow: 0.1 };   // relative % over 24h (tune after paper-testing)
let usdtSignal = 'UNKNOWN';
if (usdtD24h != null) {
  if (usdtD24h > U.riseD) usdtSignal = (usdtMcap24h != null && usdtMcap24h >= U.mcapInflow) ? 'FLIGHT_TO_USDT' : 'PRICE_DRIVEN';
  else if (usdtD24h < U.fallD) usdtSignal = 'DEPLOYING';
  else usdtSignal = 'NEUTRAL';
}

/* ---------------- macro regime ---------------- */
let macroRegime = 'MIXED', macroScore = 0;

if (btcD24h < -0.2 && total2_24h > 2 && total3_24h > 2) {
  macroRegime = 'ALT_BULL'; macroScore = 3;
}
else if (btcD24h > 0.2 && total2_24h > 1) {
  macroRegime = 'BTC_BULL'; macroScore = 2;
}
else if ((btcD24h > 0.2 && total2_24h < -2 && total3_24h < -2) ||
         (usdtSignal === 'FLIGHT_TO_USDT' && total2_24h < -2)) {      // new: real flight to USDT while alts fall
  macroRegime = 'RISK_OFF'; macroScore = -3;
}
else if (Math.abs(btcD24h) < 0.2 && total2_24h > 1 && total3_24h > 1) {
  macroRegime = 'ACCUMULATION'; macroScore = 1;
}

/* USDT nudges the score (does not change the regime by itself) */
if (macroRegime !== 'RISK_OFF') {
  if (usdtSignal === 'FLIGHT_TO_USDT') macroScore -= 1;
  else if (usdtSignal === 'DEPLOYING') macroScore += 1;
}

const f = x => (x == null ? 'n/a' : (x > 0 ? '+' : '') + x.toFixed(2) + '%');

const context = [
  `Macro Regime: ${macroRegime}`,
  `BTC.D 1H/4H/24H: ${f(btcD1h)} / ${f(btcD4h)} / ${f(btcD24h)}`,
  `TOTAL2 24H: ${f(total2_24h)}`,
  `TOTAL3 24H: ${f(total3_24h)}`,
  `USDT.D: ${usdtD == null ? 'n/a' : usdtD.toFixed(2) + '%'} (4H ${f(usdtD4h)}, 24H ${f(usdtD24h)})`,
  `USDT mcap 24H: ${f(usdtMcap24h)}`,
  `USDT signal: ${usdtSignal}`
].join(LF);

return [{
  json: {
    captured_at: new Date().toISOString(),

    total_mcap: totalMcap,
    btc_d: btcD,
    total2,
    total3,
    usdt_d: usdtD,
    usdt_mcap: usdtMcap,

    btcD_1h_change: btcD1h,
    btcD_4h_change: btcD4h,
    btcD_24h_change: btcD24h,

    total2_1h_change: total2_1h,
    total2_4h_change: total2_4h,
    total2_24h_change: total2_24h,

    total3_1h_change: total3_1h,
    total3_4h_change: total3_4h,
    total3_24h_change: total3_24h,

    usdtD_1h_change: usdtD1h,
    usdtD_4h_change: usdtD4h,
    usdtD_24h_change: usdtD24h,
    usdt_mcap_24h_change: usdtMcap24h,
    usdt_signal: usdtSignal,

    macro_score: macroScore,
    macro_regime: macroRegime,
    context
  }
}];

// Fixed watchlist; validates that each Bitget USDT perpetual exists.
const WATCHLIST=['BTC','ETH','SOL','XRP','HYPE','ZEC','DOGE','BNB','SUI','LINK','NEAR','PUMP','ADA','TAO','ENA','ASTER','WLD'];
const contracts=$('Bitget Contracts').first().json?.data||[];
const bySymbol=new Map(contracts.map(c=>[String(c.symbol||'').toUpperCase(),c]));
const out=[];
for(let i=0;i<WATCHLIST.length;i++){
  const base=WATCHLIST[i], symbol=`${base}USDT`, c=bySymbol.get(symbol);
  if(!c) continue;
  out.push({json:{symbol,baseCoin:base,productType:'usdt-futures',watchlistOrder:i+1,status:c.symbolStatus??c.status??null,minTradeNum:c.minTradeNum??null,pricePlace:c.pricePlace??null,volumePlace:c.volumePlace??null}});
}
return out;

/* INTRADAY SCREENER v2: original logic + volatility cap, real 15m cross, batch limit, cooldown, position size */
const input = $input.all(), out = [], LF = '\n';
const S = $('Build Symbols').all(), C4 =$('Candles 4h').all(), C1 = $('Candles 1h').all(), C15 =$('Candles 15m').all(), F = $('Funding Rate').all(), OI =$('Open Interest').all();

let macro = {};
try { macro = $('Compute Dominance').first().json || {}; } catch (e) {}

const CFG = {
  min4: 210, min1: 210, min15: 100, minScore: 75, minGap: 20, minVolRatio: 0.75,
  minAtrPct: 0.25,
  maxAtrPct: 1.0,          // v2: was 4. Skip alerts when 15m ATR is above 1% (market already spiking)
  maxStopPct: 3,           // v2: skip alerts whose stop is wider than 3% of entry
  crossLookback: 4,        // v2: Stoch RSI must have CROSSED within the last 4 closed 15m candles (1 hour)
  maxSignalsPerSide: 2,    // v2: at most 2 longs and 2 shorts per run
  cooldownHours: 6,        // v2: no repeat alert on the same coin + side for 6 hours (active workflow only)
  riskUsd: 100,            // v2: amount you accept to lose if the stop is hit
  leverage: { BTCUSDT: 40, default: 20 },   // v2: leverage you plan to use per coin (used for margin + liquidation check)
  maintMarginPct: 0.5,     // v2: rough maintenance margin, used to estimate the liquidation distance
  liqSafety: 0.8,          // v2: warn when the stop is further than 80% of the way to liquidation
  useDailyTrend: true,     // v2: no longs when the Daily trend is down, no shorts when it is up (needs the Candles 1d nodes)
  dailyStretchAtr: 3,      // v2: alert shows a warning when price is further than this many Daily ATRs from the Daily EMA50
  minDaily: 210,           // v2: Daily candles needed for the Daily EMA200
  maxLongFunding: .0005, minShortFunding: -.0005, rr: 2, atrStop: 1.5, maxStopAtr: 3
};

/* v2: Daily candles are optional. If the three Daily nodes are missing, the Daily rule is skipped. */
const DAILY = [];
for (const name of ['Candles 1d', 'Candles 1d older', 'Candles 1d older 2']) { try { DAILY.push($(name).all()); } catch (e) {} }

const num = x => Number.isFinite(Number(x)) ? Number(x) : null;

function candles(raw) {
  return Array.isArray(raw) ? raw.map(r => ({ t: num(r[0]), o: num(r[1]), h: num(r[2]), l: num(r[3]), c: num(r[4]), v: num(r[5]) })).filter(x => [x.t, x.o, x.h, x.l, x.c, x.v].every(Number.isFinite) && x.h >= x.l && x.c > 0).sort((a, b) => a.t - b.t) : [];
}

function emaSeries(a, p) {
  if (a.length < p) return [];
  let o = Array(a.length).fill(null), e = a.slice(0, p).reduce((s, x) => s + x, 0) / p, k = 2 / (p + 1);
  o[p - 1] = e;
  for (let i = p; i < a.length; i++) { e = a[i] * k + e * (1 - k); o[i] = e; }
  return o;
}

function last(a, n = 0) { const v = a.filter(Number.isFinite); return v[v.length - 1 - n] ?? null; }

function rsiSeries(a, p = 14) {
  if (a.length < p + 1) return [];
  let o = Array(a.length).fill(null), g = 0, l = 0;
  for (let i = 1; i <= p; i++) { let d = a[i] - a[i - 1]; d >= 0 ? g += d : l -= d; }
  g /= p; l /= p; o[p] = l === 0 ? 100 : 100 - 100 / (1 + g / l);
  for (let i = p + 1; i < a.length; i++) {
    let d = a[i] - a[i - 1], cg = Math.max(d, 0), cl = Math.max(-d, 0);
    g = (g * (p - 1) + cg) / p; l = (l * (p - 1) + cl) / p;
    o[i] = l === 0 ? 100 : 100 - 100 / (1 + g / l);
  }
  return o;
}

function sma(a, p) {
  if (a.length < p) return [];
  let o = [], s = 0;
  for (let i = 0; i < a.length; i++) {
    s += a[i]; if (i >= p) s -= a[i - p];
    if (i >= p - 1) o.push(s / p);
  }
  return o;
}

function stoch(a) {
  const r = rsiSeries(a).filter(Number.isFinite);
  if (r.length < 20) return null;
  let raw = [];
  for (let i = 13; i < r.length; i++) {
    let w = r.slice(i - 13, i + 1), mn = Math.min(...w), mx = Math.max(...w);
    raw.push(mx === mn ? 50 : (r[i] - mn) / (mx - mn) * 100);
  }
  let k = sma(raw, 3), d = sma(k, 3);
  if (k.length < 2 || d.length < 2) return null;
  /* v2: how many closed candles ago K crossed D (0 = on the latest candle); null = no cross in the lookback */
  const n = d.length, kk = k.slice(-n);
  let upAgo = null, downAgo = null;
  for (let b = 0; b < CFG.crossLookback && n - 2 - b >= 0; b++) {
    const i = n - 1 - b;
    if (upAgo === null && kk[i - 1] <= d[i - 1] && kk[i] > d[i]) upAgo = b;
    if (downAgo === null && kk[i - 1] >= d[i - 1] && kk[i] < d[i]) downAgo = b;
  }
  return { k: last(k), pk: last(k, 1), d: last(d), pd: last(d, 1), upAgo, downAgo };
}

function atr(c, p = 14) {
  if (c.length < p + 1) return null;
  let tr = [];
  for (let i = 1; i < c.length; i++) tr.push(Math.max(c[i].h - c[i].l, Math.abs(c[i].h - c[i - 1].c), Math.abs(c[i].l - c[i - 1].c)));
  let a = tr.slice(0, p).reduce((s, x) => s + x, 0) / p;
  for (let i = p; i < tr.length; i++) a = (a * (p - 1) + tr[i]) / p;
  return a;
}

function avg(a) { a = a.filter(Number.isFinite); return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null; }
function swing(c, n) { c = c.slice(-n); return { hi: Math.max(...c.map(x => x.h)), lo: Math.min(...c.map(x => x.l)) }; }
function marketStructure(candles, lookback = 40) {

    if (!candles || candles.length < lookback)
        return null;

    const data =
        candles.slice(-lookback);

    const firstHalf =
        data.slice(0, lookback / 2);

    const secondHalf =
        data.slice(lookback / 2);

    const prevHigh =
        Math.max(
            ...firstHalf.map(x => x.h)
        );

    const prevLow =
        Math.min(
            ...firstHalf.map(x => x.l)
        );

    const lastHigh =
        Math.max(
            ...secondHalf.map(x => x.h)
        );

    const lastLow =
        Math.min(
            ...secondHalf.map(x => x.l)
        );

    return {

        higherHigh:
            lastHigh > prevHigh,

        lowerHigh:
            lastHigh < prevHigh,

        higherLow:
            lastLow > prevLow,

        lowerLow:
            lastLow < prevLow,

        prevHigh,
        prevLow,
        lastHigh,
        lastLow

    };
}
/* v2: Daily trend = price against the Daily EMA50 and EMA200, plus the EMA50 slope (closed Daily candles only) */
function dailyTrend(i, livePrice) {
  const seen = new Set();
  const cd = candles(DAILY.flatMap(pg => pg[i]?.json?.data || [])).filter(c => !seen.has(c.t) && seen.add(c.t));
  if (cd.length < CFG.minDaily) return { trend: 'UNKNOWN', candles: cd.length };
  const a = cd.slice(0, -1), x = a.map(c => c.c);
  const e50s = emaSeries(x, 50), e50 = last(e50s), e50p = last(e50s, 3), e200 = last(emaSeries(x, 200)), p = last(x), atD = atr(a);
  if (![e50, e50p, e200, p, atD].every(Number.isFinite)) return { trend: 'UNKNOWN', candles: cd.length };
  const trend = p > e200 && p > e50 && e50 >= e50p ? 'UP' : p < e200 && p < e50 && e50 <= e50p ? 'DOWN' : 'MIXED';
  return { trend, candles: cd.length, ema50: e50, ema200: e200, lastClose: p, stretchAtr: (livePrice - e50) / atD };
}
function fmt(x) { return !Number.isFinite(x) ? 'n/a' : Math.abs(x) >= 100 ? x.toFixed(2) : Math.abs(x) >= 1 ? x.toFixed(3) : x.toFixed(5); }

for (let i = 0; i < input.length; i++) {
  const symbol = S[i]?.json?.symbol || `UNKNOWN_${i}`, c4 = candles(C4[i]?.json?.data), c1 = candles(C1[i]?.json?.data), c15 = candles(C15[i]?.json?.data), reject = [], reasons = [];
  let funding = 0; try { funding = num(F[i].json.data?.[0]?.fundingRate) ?? 0; } catch (e) {}
  let openInterest = null; try { openInterest = num(OI[i].json.data?.openInterestList?.[0]?.size); } catch (e) {}

  if (c4.length < CFG.min4 || c1.length < CFG.min1 || c15.length < CFG.min15) {
    out.push({ json: { symbol, hasSetup: false, side: null, regime: 'UNCERTAIN', reject: [`Candles insufficient 4H=${c4.length},1H=${c1.length},15M=${c15.length}`], message: '' } });
    continue;
  }

  const a4 = c4.slice(0, -1), a1 = c1.slice(0, -1), a15 = c15.slice(0, -1);
  const x4 = a4.map(x => x.c), x1 = a1.map(x => x.c), x15 = a15.map(x => x.c);
  const p4 = last(x4), p1 = last(x1), price = last(x15);
  const e504 = last(emaSeries(x4, 50)), e504p = last(emaSeries(x4, 50), 3), e2004 = last(emaSeries(x4, 200));
  const e501 = last(emaSeries(x1, 50)), e501p = last(emaSeries(x1, 50), 3), e2001 = last(emaSeries(x1, 200));
  const e2015 = last(emaSeries(x15, 20)), e2015p = last(emaSeries(x15, 20), 1);
  const r4 = last(rsiSeries(x4)), r1 = last(rsiSeries(x1)), r15 = last(rsiSeries(x15));
  const st = stoch(x15), at = atr(a15), atPct = at && price ? (at / price) * 100 : null, prev = last(x15, 1);
  const structure4 = marketStructure(a4);
  const vr = a15.length >= 21 ? a15[a15.length - 1].v / avg(a15.slice(-21, -1).map(x => x.v)) : null;

  const bullEMA =
    p4 > e2004 &&
    e504 > e2004 &&
    r4 >= 50;

const bearEMA =
    p4 < e2004 &&
    e504 < e2004 &&
    r4 <= 50;

const structureBull =
    structure4 &&
    structure4.higherHigh &&
    structure4.higherLow;

const structureBear =
    structure4 &&
    structure4.lowerHigh &&
    structure4.lowerLow;

let regime = 'RANGE';
/* Strong bullish structure */

if (structureBull &&
   r4 >= 55
) {
    regime = 'BULL';
}
/* Strong bearish structure */
else if (structureBear &&
    r4 <= 45
) {
    regime = 'BEAR';
}
/* Momentum fallback */
else if (
    r4 >= 60
) {
  regime = 'BULL';
}
else if (
    r4 <= 40
) {
  regime = 'BEAR';
}
else {
  regime = 'RANGE';
}
  const bull1 = p1 > e2001 && e501 > e2001 && e501 >= e501p && r1 >= 52, bear1 = p1 < e2001 && e501 < e2001 && e501 <= e501p && r1 <= 48;
  /* v2: a fresh cross is required, and K must still be on the right side of D */
  const bullTrig = !!st && st.upAgo !== null && st.k > st.d && price > e2015;
  const bearTrig = !!st && st.downAgo !== null && st.k < st.d && price < e2015;
  const volOK = vr >= CFG.minVolRatio, atrOK = atPct >= CFG.minAtrPct && atPct <= CFG.maxAtrPct;

  let longScore = 0;
  let shortScore = 0;
  /* EMA trend score */
  if (p4 > e2004) longScore += 15; 
  else shortScore += 15;
  if (e504 > e2004) longScore += 15; 
  else shortScore += 15;
  if (e504 > e504p) longScore += 10; 
  else shortScore += 10;
  /* Market Structure score */
  if(
    structureBull
){
    longScore += 20;
}

if(
    structureBear
){
    shortScore += 20;
}
/* Regime score */
if(
    regime === 'BULL'
) {
    longScore += 20;
}
else if (
    regime === 'BEAR'
) {
    shortScore += 20;
}
  if (r4 >= 65) longScore += 15;
  else if (r4 >= 60) longScore += 10;
  if (r4 <= 35) shortScore += 15;
  else if (r4 <= 40) shortScore += 10;

  if (bull1) longScore += 20;
  if (bear1) shortScore += 20;
  if (bullTrig) longScore += 30;
  if (bearTrig) shortScore += 30;
  if (volOK && price > prev) longScore += 15;
  if (volOK && price < prev) shortScore += 15;

  let longAllowed = true, shortAllowed = true;
  if(regime === 'BEAR'){ longAllowed = false; } 
  if(regime === 'BULL'){ shortAllowed = false; }
  if(regime === 'BEAR'){ 
    longScore -= 30; shortScore += 20; 
  } 
  else if(regime === 'BULL'){ 
    longScore += 20; shortScore -= 30; 
  }

  if(symbol === 'BTCUSDT') {
    if(macro.macro_regime === 'BTC_BULL'){longScore +=15;}
  }else{
    switch (macro.macro_regime) {
      case 'ALT_BULL':
        longScore += 15;
        break;

      case 'RISK_OFF':
        shortScore += 20;
        longScore -= 15;
        longAllowed = false;
        break;

      case 'ACCUMULATION':
        longScore += 5;
        break;
    }
  }

  if (funding > CFG.maxLongFunding) longScore -= 10;
  if (funding < CFG.minShortFunding) shortScore -= 10;
  longScore = Math.max(0, Math.min(100, longScore));
  shortScore = Math.max(0, Math.min(100, shortScore));

  const daily = dailyTrend(i, price);
  if (CFG.useDailyTrend && daily.trend === 'DOWN') longAllowed = false;
  if (CFG.useDailyTrend && daily.trend === 'UP') shortAllowed = false;
  let side = null;
  if (longAllowed && regime === 'BULL' && bull1 && bullTrig && volOK && atrOK && funding <= CFG.maxLongFunding && longScore >= CFG.minScore && longScore - shortScore >= CFG.minGap) side = 'long';
  else if (shortAllowed && regime === 'BEAR' && bear1 && bearTrig && volOK && atrOK && funding >= CFG.minShortFunding && shortScore >= CFG.minScore && shortScore - longScore >= CFG.minGap) side = 'short';

  if (!side) {
    if (regime === 'RANGE') reject.push('4H RANGE');
    if (CFG.useDailyTrend && ((regime === 'BULL' && daily.trend === 'DOWN') || (regime === 'BEAR' && daily.trend === 'UP'))) reject.push(`Daily trend is ${daily.trend}: no ${regime === 'BULL' ? 'longs' : 'shorts'} against it`);
    if (!volOK) reject.push(`Volume ratio ${fmt(vr)} below threshold`);
    if (!atrOK) reject.push(`ATR ${fmt(atPct)}% outside range`);
    const want = regime === 'BULL' ? 'long' : regime === 'BEAR' ? 'short' : null;
    if (want) {
      if (!(want === 'long' ? bull1 : bear1)) reject.push('1H trend not confirmed');
      if (!(want === 'long' ? bullTrig : bearTrig)) reject.push(st && (want === 'long' ? st.k > st.d && price > e2015 : st.k < st.d && price < e2015)
        ? `15M trigger is stale: no Stoch RSI cross in the last ${CFG.crossLookback} candles` : '15M trigger missing');
    }
    reject.push('No aligned 4H/1H/15M setup');
  }

  let entry = null, sl = null, tp = null, trailPct = null, message = '', stopPct = null, qty = null, notional = null, lev = null, margin = null, liqPct = null, safeLev = null;
  if (side) {
    entry = price;
    let sw = swing(a15, 20), risk = side === 'long' ? entry - sw.lo : sw.hi - entry;
    risk = Math.max(CFG.atrStop * at,risk);
    risk = Math.min(risk, CFG.maxStopAtr * at);
    sl = side === 'long' ? entry - risk : entry + risk;
    tp = side === 'long' ? entry + CFG.rr * risk : entry - CFG.rr * risk;
    trailPct = Math.max(.5, Math.round(at / entry * 12000) / 100);
    stopPct = risk / entry * 100;
    qty = CFG.riskUsd / risk; notional = qty * entry;
    lev = CFG.leverage[symbol] ?? CFG.leverage.default;
    margin = notional / lev;
    liqPct = 100 / lev - CFG.maintMarginPct;                     // approximate adverse move that liquidates an isolated position
    safeLev = Math.max(1, Math.floor(100 / (stopPct / CFG.liqSafety + CFG.maintMarginPct)));
    if (stopPct > CFG.maxStopPct) { reject.push(`Stop ${stopPct.toFixed(2)}% wider than ${CFG.maxStopPct}%`); side = null; }
  }
  if (side) {
    if(side) {
    reasons.push(`${regime} 4H`);
reasons.push(`1H confirmed`);
reasons.push(`15M Stoch RSI cross ${side === 'long' ? st.upAgo : st.downAgo} candle(s) ago + EMA20 trigger`);
reasons.push(`Volume ${fmt(vr)}x`);
    }
    message = [`${side.toUpperCase()} setup: ${symbol} [v2]`, `Macro: ${macro.macro_regime}`, `4H Regime: ${regime}`, `Long Score: ${longScore}`, `Short Score: ${shortScore}`, `Entry ${fmt(entry)} | SL ${fmt(sl)} (${stopPct.toFixed(2)}%) | TP ${fmt(tp)}`, `Size for $${CFG.riskUsd} risk: ${fmt(qty)} ${symbol.replace('USDT', '')} (about $${Math.round(notional)} position)`, ...(() => { const st_ = daily.stretchAtr, far = Number.isFinite(st_) && (side === 'short' ? st_ < -CFG.dailyStretchAtr : st_ > CFG.dailyStretchAtr); return [daily.trend === 'UNKNOWN' ? `Daily trend: unknown (${daily.candles} Daily candles)` : `Daily trend: ${daily.trend} | price is ${Math.abs(st_).toFixed(1)} Daily ATR ${st_ < 0 ? 'below' : 'above'} EMA50`, ...(far ? [`WARNING: stretched on the Daily chart. ${side === 'short' ? 'Bounce' : 'Pullback'} risk is high; consider skipping or smaller size.`] : [])]; })(), `At ${lev}x: margin about $${Math.round(margin)}, liquidation roughly ${liqPct.toFixed(2)}% away (estimate)`, ...(stopPct > CFG.liqSafety * liqPct ? [`WARNING: stop (${stopPct.toFixed(2)}%) is too close to liquidation at ${lev}x. Use ${safeLev}x or lower for this trade.`] : []), `ATR ${fmt(atPct)}%`, `Volume Ratio: ${fmt(vr)}x`, `Funding: ${Number.isFinite(funding) ? (funding * 100).toFixed(4) : 0}%`, `RSI 4H/1H/15M: ${fmt(r4)}/${fmt(r1)}/${fmt(r15)}`, '', ...reasons.map(x => `• ${x}`), '', 'Macro Details:', macro.context || '', 'Proposal only; paper-test before live execution.'].join(LF);
  }

  out.push({ json: { symbol, hasSetup: !!side, side, regime, macroRegime: macro.macro_regime || null, longScore, shortScore, entry, sl, tp, trailPct, stopPct, qty, notional, dailyTrend: daily.trend, dailyStretchAtr: daily.stretchAtr ?? null, dailyCandles: daily.candles, leverage: lev, margin, liqPct, safeLeverage: safeLev, crossAgo: st ? (side === 'long' ? st.upAgo : side === 'short' ? st.downAgo : null) : null, funding, openInterest, atrPct: atPct, volumeRatio: vr, rsi4h: r4, rsi1h: r1, rsi15m: r15, reasons, rejectionReasons: reject, message } });
}

/* ---- v2: batch limit + cooldown ---- */
/* Cooldown uses workflow static data, which is saved only when the workflow is ACTIVE (not in manual test runs). */
let sd = {}; try { sd = $getWorkflowStaticData('global'); } catch (e) {}
sd.lastSignal = sd.lastSignal || {};
const nowMs = Date.now(), counts = { long: 0, short: 0 };
const block = (j, why) => { j.rejectionReasons.push(why); j.blockedSide = j.side; j.hasSetup = false; j.side = null; j.message = ''; };
out.filter(o => o.json.hasSetup)
  .sort((a, b) => (Math.max(b.json.longScore, b.json.shortScore) - Math.max(a.json.longScore, a.json.shortScore)) || (a.json.crossAgo - b.json.crossAgo) || (b.json.volumeRatio - a.json.volumeRatio))
  .forEach(o => {
    const j = o.json, key = j.symbol + ':' + j.side, prev = sd.lastSignal[key];
    if (prev && nowMs - prev < CFG.cooldownHours * 3600e3) return block(j, `Cooldown: same alert ${((nowMs - prev) / 3600e3).toFixed(1)}h ago`);
    if (counts[j.side] >= CFG.maxSignalsPerSide) return block(j, `Batch limit: already ${CFG.maxSignalsPerSide} ${j.side} alerts this run`);
    counts[j.side]++; sd.lastSignal[key] = nowMs;
  });
return out;

